\u006d\u005d\u002c\u004a\u0059\u0077\u006a\u0065\u0037\u003e\u0069\u006a\u007a\u007d\u004b\u0028\u0069\u007c\u004d\u003b\u0077\u0044\u0061\u004d\u006f\u006f\u004f\u0037\u004d\u007e\u005d\u006e\u007d\u0042\u003e\u0021\u0036\u0035\u0025\u004a\u006f\u0078\u0054\u002f\u003d\u004c\u0072\u0038\u002a\u0050\u004c\u0057\u006a\u0036\u0021\u0058\u002c\u002c\u0023\u007e\u003d\u003f\u0076\u0063\u0069\u0022\u0069\u0064\u0053\u003f\u0026\u0041\u0033\u005b\u0068\u0033\u0033\u0052\u006e\u007d\u0042\u003e\u0021\u0036\u0035\u0025\u004a\u006f\u0078\u0054\u002f\u003d\u004c\u0072\u0038\u002a\u0050\u004c\u0057\u006a\u0036\u0021\u0058\u002c\u0058\u0067\u0077\u006a\u007b\u0037\u0077\u004f\u005e\u006c\u003f\u007e\u0068\u007c\u006f\u0047\u002c\u003e\u005b\u003e\u0028\u0028\u0043\u0059\u002a\u0060\u0076\u004a\u0078\u004d\u0026\u006c\u0064\u003d\u006b\u0062\u006e\u0038\u0078\u003f\u0053\u004b\u005d\u0024\u0062\u0079\u0059\u0069\u0030\u0040\u006b\u007d\u0031\u005b\u002a\u005f\u0038\u0049\u005e\u0037\u003c\u002c\u0038\u0047\u0053\u0049\u005b\u0055\u005f\u0053\u0064\u004a\u002a\u0024\u0053\u005a\u0062\u006a\u0068\u0032\u0052\u0028\u0073\u0055\u0049\u006b\u0049\u006b\u0068\u0045\u0051\u0036\u0031\u0026\u0021\u004a\u0051\u007c\u0051\u007e\u003c\u0047\u0046\u0069\u0029\u0044\u0052\u0025\u006f\u0041\u0067\u005a\u0045\u002c\u0022\u003d\u005f\u005f\u0056\u0040\u004c\u0054\u0036\u0043\u005b\u0044\u0073\u0068\u0023\u0030\u006c\u004f\u0074\u0047\u002e\u0063\u0059\u002e\u0078\u0072\u004d\u004c\u003e\u0048\u0059\u002f\u0044\u0035\u005f\u0070\u002b\u002e\u0077\u0038\u0063\u0033\u003e\u0037\u007d\u005d\u0022\u005a\u0052\u007e\u0071\u006b\u0037\u0068\u0031\u0048\u003f\u0054\u005e\u0034\u006f\u0062\u004c\u0045\u0059\u007e\u0068\u007b\u006f\u0070\u0030\u003e\u006a\u003c\u0044\u0058\u004f\u0041\u003d\u002e\u0077\u0060\u0021\u003f\u0043\u002f\u004d\u0062\u0048\u0021\u0057\u003f\u0047\u0059\u0063\u0045\u0026\u0062\u007a\u003c\u0029\u007c\u0077\u005b\u0072\u0054\u0078\u007d\u006e\u0046\u0049\u004b\u0043\u0050\u0044\u003e\u005e\u003c\u0030\u003c\u003f\u005e\u0034\u006f\u0076\u002a\u0045\u0039\u002a\u0063\u003b\u0047\u0057\u005a\u003a\u0051\u004f\u0026\u003f\u0037\u0034\u0067\u0076\u0035\u0045\u0074\u0055\u0024\u003f\u004b\u0026\u0044\u007d\u007e\u0045\u005b\u007e\u005a\u0040\u0043\u0054\u0041\u0043\u0043\u006f\u0077\u005a\u0049\u0024\u0072\u002a\u002b\u006c\u0045\u003e\u0023\u0049\u0042\u006f\u0025\u0076\u0057\u002c\u0057\u006d\u0048\u0074\u0023\u006f\u0072\u0053\u0023\u002b\u004a\u0062\u002a\u0045\u0041\u005a\u0072\u0072\u005b\u0043\u0065\u0064\u0063\u0022\u0050\u0045\u0040\u0023\u0045\u0034\u0053\u005b\u0049\u0059\u0041\u0044\u006f\u0062\u004b\u003c\u0052\u0057\u0074\u0046\u002a\u0028\u0075\u0078\u004a\u006c\u0036\u005e\u0025\u002b\u007d\u0072\u002c\u0054\u0053\u0074\u0060\u007a\u005f\u0043\u0031\u006f\u0031\u0076\u004f\u007d\u0078\u0078\u0054\u006d\u006f\u003c\u0050\u0042\u0060\u004d\u0057\u0067\u0052\u0078\u004a\u0065\u0066\u002b\u0072\u004d\u0057\u004e\u002e\u006b\u0024\u0031\u007e\u0024\u0071\u003d\u007d\u005d\u0050\u0050\u0036\u0043\u002f\u002b\u007b\u0050\u0045\u0072\u0063\u0046\u002b\u0056\u0056\u003e\u003a\u0052\u0055\u003b\u0070\u0065\u004a\u0074\u0029\u0045\u005e\u003d\u0031\u003a\u0052\u007b\u003b\u0053\u0059\u004a\u0074\u0029\u0045\u004a\u005f\u004a\u003f\u007e\u0063\u0076\u0022\u0049\u0045\u0074\u007d\u0074\u002f\u0033\u003e\u0028\u0034\u006f\u0062\u0050\u0045\u0077\u0055\u0074\u004e\u0030\u006d\u002f\u0051\u007b\u0024\u0024\u0049\u007e\u005d\u0044\u0050\u007b\u0042\u0025\u003f\u0051\u0034\u0067\u0077\u005b\u003c\u005d\u0021\u0023\u006f\u0041\u0042\u0068\u003a\u0079\u0063\u004a\u007c\u002a\u0036\u007e\u002a\u005b\u0073\u0044\u003d\u0047\u007c\u0023\u005e\u007e\u007b\u0051\u0044\u0077\u0052\u004c\u0071\u005f\u0040\u0067\u005b\u0075\u0033\u0049\u0052\u007e\u002c\u005b\u0058\u0076\u0040\u002e\u0062\u0026\u0029\u0065\u0031\u003d\u005e\u0079\u0043\u0054\u0053\u0022\u0040\u0078\u004d\u0063\u006a\u006f\u0075\u007a\u003b\u004d\u003e\u0033\u003d\u0030\u007b\u0051\u0045\u0036\u004b\u006c\u007e\u0035\u005b\u0072\u0055\u004d\u006b\u0040\u0047\u0054\u0049\u0047\u0065\u006d\u0072\u0060\u002b\u0047\u0029\u0048\u0055\u0043\u003c\u0044\u006f\u0062\u0068\u006c\u0056\u0041\u002c\u0031\u0063\u005b\u0038\u0067\u0053\u002f\u0026\u0048\u0058\u004a\u0022\u006d\u0042\u0078\u0066\u0029\u0069\u0035\u0021\u0064\u003a\u0064\u0034\u006e\u0048\u0059\u0043\u002f\u0062\u005d\u0050\u0045\u005f\u004d\u0060\u0061\u0073\u0044\u005d\u0025\u003b\u0022\u0050\u0045\u0050\u0071\u002c\u0031\u0057\u002a\u0032\u0050\u0044\u0025\u004c\u004e\u0075\u0041\u006e\u0050\u004c\u0077\u0050\u006b\u0078\u002f\u006b\u0031\u0077\u0068\u0038\u0034\u005e\u006f\u004d\u003c\u005a\u0038\u0035\u007e\u0032\u0056\u0069\u004b\u0062\u0059\u0045\u0067\u0022\u0077\u0071\u0055\u0023\u0043\u0056\u007b\u0061\u0042\u0038\u005f\u0036\u002f\u003f\u005d\u0075\u0029\u0050\u003e\u005d\u004c\u0067\u0050\u0045\u0050\u002e\u0077\u0026\u0065\u0030\u006a\u0068\u0076\u0021\u0043\u0065\u0051\u002f\u0049\u0075\u0054\u003f\u0033\u005a\u0046\u0075\u003d\u0049\u004f\u005b\u0077\u0049\u007a\u0038\u0033\u0071\u006a\u004d\u0033\u0059\u002c\u0023\u0043\u0029\u0031\u0026\u007a\u007d\u0064\u002a\u004c\u0036\u0055\u004d\u0029\u0066\u0043\u003d\u0025\u0050\u006c\u0049\u006b\u0049\u006b\u0068\u0032\u003f\u0058\u0056\u0052\u0079\u006f\u0044\u007a\u0024\u007b\u0037\u0031\u0064\u0036\u0058\u0051\u003e\u0067\u005a\u0062\u0039\u0026\u0037\u0069\u004a\u004f\u0066\u0044\u0071\u003b\u0051\u006e\u003d\u0067\u0038\u0066\u006b\u0060\u0065\u0032\u006b\u0035\u005f\u0040\u004c\u003b\u0047\u007c\u0035\u002e\u0037\u0066\u003b\u004c\u006b\u002a\u0076\u0076\u007a\u0057\u0023\u004e\u0044\u005e\u0053\u0056\u003e\u0069\u0038\u0028\u0042\u0061\u002f\u007a\u0042\u004a\u0041\u005f\u0078\u0037\u0063\u0022\u0024\u0041\u0065\u0033\u005f\u0055\u0039\u0043\u006d\u0064\u0028\u0031\u0077\u0029\u0032\u006c\u0032\u002b\u0066\u0024\u004b\u0035\u0032\u0056\u0036\u0026\u0066\u0036\u007c\u0029\u0070\u0035\u004d\u0028\u0035\u0050\u004a\u006e\u0066\u0060\u0025\u0056\u0055\u002a\u0026\u0070\u0066\u006e\u0076\u005d\u0025\u0058\u004c\u0079\u0034\u006b\u003e\u0060\u0025\u0068\u0068\u004e\u0059\u0038\u007a\u004e\u0033\u0045\u006d\u006b\u003e\u005d\u004d\u0068\u007a\u0039\u0059\u0044\u0058\u002a\u004f\u002c\u0060\u006e\u005a\u005f\u0035\u0040\u0025\u0055\u002b\u0023\u0029\u0077\u002b\u0036\u0030\u006c\u0040\u0043\u003d\u0079\u006f\u0067\u006a\u0062\u002f\u0043\u0046\u0075\u006c\u003d\u006a\u0060\u0072\u0069\u006e\u006c\u002f\u007b\u0077\u006e\u006e\u005f\u007e\u0031\u0050\u004d\u0032\u003e\u002a\u0044\u0036\u0055\u0029\u0033\u0077\u0064\u0066\u0045\u003a\u005d\u0034\u0041\u0060\u004d\u0031\u0054\u0040\u006f\u0059\u006f\u0065\u0065\u0062\u006c\u004c\u003b\u007e\u0037\u0029\u003f\u0073\u005d\u006a\u0051\u007c\u002c\u0056\u0025\u0029\u0034\u0069\u004b\u0072\u004f\u002c\u0033\u006c\u004e\u004a\u0039\u007c\u0052\u006e\u0059\u004c\u0035\u0025\u002e\u003a\u0064\u0043\u0040\u0025\u0054\u0069\u002e\u0059\u0063\u003d\u0048\u0065\u0025\u005d\u004d\u0064\u0077\u0021\u0059\u003e\u0047\u004e\u002f\u004e\u0061\u0025\u0058\u0032\u005e\u0059\u004f\u0052\u0069\u0034\u0048\u0026\u005b\u0029\u005f\u007a\u002c\u0056\u0021\u007d\u005f\u0055\u005f\u0037\u0025\u0078\u0070\u002e\u0072\u0054\u0023\u005f\u0062\u0073\u004c\u004d\u0068\u002f\u0071\u002f\u0070\u002e\u0025\u007c\u005b\u0033\u004c\u0045\u0034\u005a\u0025\u0026\u0070\u0070\u0052\u0050\u005d\u003b\u0058\u006b\u0043\u0034\u006b\u0046\u006b\u0024\u006e\u005f\u0035\u0040\u0025\u0045\u0061\u0025\u006c\u0069\u0040\u0072\u003b\u004f\u0024\u0047\u0039\u0061\u0024\u006a\u0071\u0075\u0036\u004d\u0034\u0030\u0032\u003d\u002f\u002c\u0048\u0047\u0052\u006a\u004c\u0078\u0026\u0074\u005a\u0029\u0057\u0048\u0076\u007a\u0066\u007d\u006f\u002a\u006a\u002b\u006d\u002a\u006d\u0046\u005a\u002f\u0025\u007c\u0029\u0049\u0065\u0066\u0047\u0052\u006a\u0060\u006d\u0074\u0047\u0059\u0065\u0071\u0039\u004d\u0048\u0035\u0034\u0037\u0069\u0047\u0059\u006a\u006f\u0075\u003d\u0078\u004c\u0071\u0034\u0021\u0059\u0070\u0032\u003e\u0031\u0044\u0028\u0079\u0026\u0054\u006f\u006f\u005b\u0058\u003e\u005a\u004e\u005b\u0074\u0067\u0029\u0039\u0041\u006a\u0033\u002b\u0050\u0035\u0079\u0026\u0054\u006f\u006f\u005b\u0055\u0052\u004c\u002c\u0060\u0066\u0069\u0023\u0026\u0037\u007b\u0054\u003b\u0055\u0044\u007d\u006d\u0026\u0078\u0066\u0059\u005b\u0039\u002b\u0044\u0032\u004e\u0021\u0077\u0030\u003e\u0028\u003a\u0028\u0058\u005e\u0041\u007c\u0078\u0022\u0048\u0067\u005a\u0051\u002e\u0045\u0059\u003d\u0042\u0033\u005e\u0077\u006a\u0071\u005f\u007e\u0023\u0030\u0045\u0026\u004a\u0055\u007d\u0026\u0064\u0074\u005d\u0043\u0062\u0026\u0049\u004d\u0069\u004a\u004f\u0073\u0039\u0078\u005a\u0056\u0064\u0030\u0022\u0039\u0029\u007a\u004c\u007d\u0053\u007d\u0076\u0040\u0021\u0069\u0071\u004c\u005b\u006d\u0026\u006d\u004b\u0075\u0033\u0065\u007d\u0041\u0067\u0043\u0042\u007e\u0031\u005a\u0036\u006c\u006f\u0043\u005e\u0078\u0024\u004f\u0040\u0069\u004d\u0041\u0051\u0039\u0055\u003b\u0052\u005e\u005b\u002e\u004c\u006f\u0062\u003d\u0069\u0033\u0069\u0032\u004a\u002e\u0053\u0064\u006c\u003c\u006f\u0041\u004e\u005e\u0049\u0064\u0025\u004a\u006b\u0021\u0077\u0052\u0066\u005f\u0035\u002a\u0063\u0025\u003b\u003a\u0031\u0078\u0077\u0044\u0047\u003f\u0032\u0075\u0052\u007b\u0062\u0052\u0023\u0077\u002c\u007d\u005a\u0035\u0040\u005e\u0062\u0053\u0040\u005d\u003e\u007b\u0079\u0062\u005e\u005f\u006a\u0059\u0070\u003a\u003d\u005b\u0058\u004b\u005b\u0048\u0075\u0059\u004b\u0024\u0056\u0034\u006a\u0077\u0056\u0028\u0034\u007c\u0047\u0038\u003b\u006a\u005a\u0029\u0033\u004e\u006b\u0075\u0047\u0059\u0033\u004b\u0024\u004e\u0030\u0056\u0063\u0059\u0065\u007d\u0032\u002e\u003d\u0059\u0024\u0053\u0064\u004d\u005e\u003d\u0070\u0032\u0034\u0042\u002e\u0025\u005e\u0072\u0057\u0031\u0073\u0021\u0032\u005a\u0071\u0041\u0052\u0047\u0077\u0025\u005f\u006f\u0039\u0049\u0060\u006f\u003b\u0062\u004a\u0050\u006a\u006b\u002c\u0053\u002e\u0053\u0064\u003a\u0069\u0049\u004e\u0065\u003b\u002a\u0064\u0064\u0055\u0075\u003d\u0028\u005e\u0048\u0047\u0022\u0069\u003c\u0040\u0047\u0052\u002a\u003a\u0047\u002f\u0057\u004a\u007d\u002a\u0054\u004c\u006a\u0060\u003c\u0061\u0026\u006f\u0076\u0071\u0053\u0061\u0054\u0048\u0024\u002b\u003a\u002a\u0076\u0026\u0064\u0078\u003c\u002f\u006d\u0040\u002e\u004d\u003b\u002e\u007e\u0041\u006f\u0060\u0055\u004f\u0046\u0035\u0043\u0060\u0076\u0052\u007b\u003f\u0075\u0035\u005a\u0046\u0053\u006e\u004a\u0033\u005a\u0074\u0040\u006a\u0021\u003b\u0078\u0061\u006e\u0070\u0062\u006d\u005e\u0052\u0070\u0035\u006d\u0040\u0060\u0032\u0047\u0070\u0062\u007c\u0036\u003c\u007a\u0023\u002e\u0075\u005d\u0062\u0034\u0040\u0055\u0031\u005a\u0072\u0076\u0046\u0069\u0021\u0030\u0055\u006e\u0070\u0025\u005b\u0023\u004b\u0044\u0069\u004a\u0044\u0045\u0072\u0056\u0066\u005b\u003a\u007b\u0079\u0079\u0033\u0073\u006a\u0044\u0048\u0058\u0063\u0036\u0055\u0077\u0064\u0030\u0078\u0024\u004f\u0040\u0069\u004d\u0041\u0051\u003e\u003a\u0056\u0059\u0060\u007d\u0054\u0030\u007e\u003d\u006b\u0041\u0064\u004a\u0045\u0028\u0069\u0056\u0052\u0021\u006b\u003c\u0032\u0059\u0070\u0028\u0024\u0034\u0072\u005e\u0058\u0033\u0024\u0069\u002b\u007b\u0037\u0055\u0077\u003e\u0066\u0024\u0024\u004c\u0026\u006b\u007c\u0021\u0066\u0022\u006b\u007e\u004d\u0058\u006e\u0060\u007d\u0052\u0069\u005b\u0066\u004e\u0055\u004f\u0054\u004a\u006e\u0078\u0054\u004a\u0040\u0069\u004d\u005d\u006e\u0061\u0079\u0059\u0022\u0029\u0043\u0072\u0021\u004c\u0024\u0047\u0074\u0055\u0037\u002c\u0066\u0055\u006b\u003c\u0050\u006f\u0056\u006d\u0038\u005b\u0055\u0075\u0036\u0045\u003f\u003c\u003d\u005a\u0066\u0026\u0039\u0047\u0029\u0055\u0023\u007e\u0058\u0034\u005a\u005f\u0067\u003e\u0066\u0073\u0030\u0038\u005e\u004a\u0075\u0033\u003d\u0035\u0046\u004f\u003f\u0047\u0063\u006e\u0024\u0055\u003d\u002a\u0062\u003d\u0035\u0025\u003b\u0047\u0059\u0026\u0045\u0070\u007a\u0063\u0079\u0078\u0071\u004e\u002a\u0052\u005a\u0037\u0025\u0024\u0077\u005e\u007b\u007b\u0036\u003f\u005b\u003b\u004b\u006b\u0053\u0058\u0035\u0023\u0053\u0038\u007e\u006d\u005e\u0071